LESSONS = [
    {"id":"thinking-threat","section":"Мышление","title":"Что изменил последний ход соперника?","level":"600–1200","summary":"Перед своим планом сначала проверь, что нового появилось у соперника.","steps":["Назови фигуру, которая только что сходила.","Проверь, что она теперь атакует.","Посмотри, какие линии она открыла или закрыла.","Проверь шахи, взятия и прямые угрозы соперника."],"question":"Что нужно сделать первым после хода соперника?","options":["Сразу искать свою атаку","Проверить, что изменилось и чем он угрожает","Двигать пешку в центре"],"answer":1,"explanation":"Сначала нужно понять смысл последнего хода соперника. Иначе легко продолжить свой план и пропустить угрозу."},
    {"id":"thinking-cct","section":"Мышление","title":"Шахи — взятия — угрозы","level":"700–1300","summary":"Форсированные ходы проверяем раньше спокойных позиционных идей.","steps":["Найди все легальные шахи.","Проверь все взятия.","Найди прямые атаки на незащищённые фигуры.","Только потом переходи к позиционному плану."],"question":"Если у тебя есть красивый позиционный ход и выигрыш ферзя за два хода, что проверять первым?","options":["Позиционный ход","Форсированную тактику","Рокировку"],"answer":1,"explanation":"Тактика обычно важнее долгосрочного плана: один форсированный вариант может решить всю партию."},
    {"id":"mate-one","section":"Мат","title":"Мат в один: обязательная проверка","level":"400–900","summary":"Приучаемся перед каждым ходом задавать вопрос: есть ли мат прямо сейчас?","steps":["Перечисли все шахи.","Для каждого шаха проверь клетки отхода короля.","Проверь, можно ли съесть атакующую фигуру.","Проверь, можно ли закрыться от шаха."],"question":"Почему полезно искать мат до обычного шаха?","options":["Мат сразу заканчивает партию","Так быстрее развиваются фигуры","Мат улучшает пешечную структуру"],"answer":0,"explanation":"Если мат есть, все остальные планы больше не нужны."},
    {"id":"mate-threat","section":"Мат","title":"Как не пропустить мат соперника","level":"600–1100","summary":"Учимся распознавать матовую сеть до того, как станет поздно.","steps":["Посмотри, какие фигуры соперника направлены на короля.","Проверь слабые поля возле короля.","Ищи двойные атаки ферзя и слона/ладьи.","Проверь возможность размена атакующих фигур."],"question":"Что важнее при прямой угрозе мата?","options":["Продолжать свою атаку","Сначала нейтрализовать угрозу","Взять случайную пешку"],"answer":1,"explanation":"Угроза мата требует немедленной реакции, если у тебя нет более сильного форсированного продолжения."},
    {"id":"opening-dev","section":"Дебют","title":"Закончи развитие","level":"400–900","summary":"В дебюте естественные развивающие ходы почти всегда важнее случайных атак.","steps":["Выведи коней и слонов.","Борись за центр.","Сделай рокировку.","Соедини ладьи."],"question":"Что обычно хуже в начале партии?","options":["Развить коня","Сделать рокировку","Третий раз сходить одной и той же фигурой без причины"],"answer":2,"explanation":"Повторные ходы одной фигурой часто отдают темпы и оставляют остальные фигуры вне игры."},
    {"id":"opening-queen","section":"Дебют","title":"Почему не стоит рано выводить ферзя","level":"400–900","summary":"Ранний ферзь часто становится мишенью и помогает сопернику развиваться с темпом.","steps":["Проверь, можно ли атаковать ферзя развивающим ходом.","Считай потерянные темпы.","Не начинай ферзевую атаку без поддержки фигур."],"question":"В чём главная опасность раннего выхода ферзя?","options":["Ферзь слишком слабый","Его могут атаковать, развивая фигуры с темпом","Ферзь не умеет брать пешки"],"answer":1,"explanation":"Соперник получает развитие бесплатно, пока ферзь вынужден отходить."},
    {"id":"opening-castle","section":"Дебют","title":"Когда рокировать","level":"500–1000","summary":"Безопасность короля — одна из главных задач дебюта.","steps":["Освободи путь для рокировки.","Проверь, не опасна ли сторона рокировки.","Не оставляй короля в центре при открывающемся центре."],"question":"Когда особенно опасно задерживать рокировку?","options":["Когда центр открывается","Когда все пешки стоят на месте","Когда у соперника нет фигур"],"answer":0,"explanation":"В открытом центре король быстро попадает под удары тяжёлых фигур."},
    {"id":"tactic-fork","section":"Тактика","title":"Вилка","level":"500–1000","summary":"Одна фигура одновременно атакует две или больше целей.","steps":["Ищи поля, откуда конь атакует две дорогие фигуры.","Проверяй пешечные вилки.","Не забывай ферзевые и королевские двойные атаки."],"question":"Почему вилка сильна?","options":["Соперник обычно не может спасти обе цели одним ходом","Она всегда даёт мат","Она меняет цвет поля"],"answer":0,"explanation":"Две одновременные угрозы часто заставляют соперника потерять материал."},
    {"id":"tactic-pin","section":"Тактика","title":"Связка","level":"600–1100","summary":"Фигура не может или не хочет двигаться, потому что за ней стоит более ценная цель.","steps":["Найди короля или ферзя за фигурой.","Проверь линию слона, ладьи или ферзя.","Усиль давление на связанную фигуру."],"question":"Какая связка называется абсолютной?","options":["Фигура связана с королём","Фигура связана с пешкой","Две пешки стоят рядом"],"answer":0,"explanation":"Если движение фигуры откроет шах королю, такой ход вообще нелегален."},
    {"id":"tactic-skewer","section":"Тактика","title":"Сквозной удар","level":"700–1200","summary":"Более ценная фигура вынуждена уйти, открывая менее ценную цель позади.","steps":["Ищи выстроенные на одной линии фигуры.","Поставь под удар более ценную фигуру.","После её отхода забери вторую."],"question":"Чем сквозной удар отличается от связки?","options":["Впереди обычно стоит более ценная фигура","Ничем","Он бывает только конём"],"answer":0,"explanation":"При сквозном ударе первая фигура уходит и открывает вторую цель."},
    {"id":"tactic-discovery","section":"Тактика","title":"Вскрытое нападение","level":"700–1200","summary":"Одна фигура уходит и открывает линию другой.","steps":["Ищи свои линейные фигуры за блокирующей фигурой.","Найди ход блокирующей фигуры с темпом.","Проверь двойной удар после вскрытия линии."],"question":"Что делает вскрытое нападение опасным?","options":["Один ход создаёт две активности сразу","Фигура исчезает","Всегда забирается король"],"answer":0,"explanation":"Уходящая фигура может сама создать угрозу, одновременно открывая новую атаку другой фигуры."},
    {"id":"tactic-overload","section":"Тактика","title":"Перегруженная фигура","level":"800–1300","summary":"Защитник не может одновременно выполнять две важные задачи.","steps":["Найди фигуру, защищающую несколько целей.","Атакуй одну из защищаемых целей.","После отвлечения используй вторую слабость."],"question":"Что такое перегрузка?","options":["Фигура защищает слишком много важных объектов","Слишком много пешек","Слишком длинная партия"],"answer":0,"explanation":"Один защитник физически не может ответить на две разные угрозы одновременно."},
    {"id":"tactic-deflection","section":"Тактика","title":"Отвлечение защитника","level":"800–1300","summary":"Заставляем важную защитную фигуру покинуть её пост.","steps":["Определи ключевого защитника.","Найди форсированный способ заставить его уйти.","После отвлечения используй освободившуюся цель."],"question":"Главная цель отвлечения?","options":["Увести защитника от важного поля или фигуры","Развить коня","Создать проходную пешку всегда"],"answer":0,"explanation":"Тактика работает, когда защитник после вынужденного хода больше не выполняет прежнюю функцию."},
    {"id":"material-value","section":"Материал","title":"Ценность фигур и контекст","level":"400–900","summary":"3, 3, 5, 9 — это ориентир, а не абсолютная истина.","steps":["Пешка ≈ 1.","Конь и слон ≈ 3.","Ладья ≈ 5.","Ферзь ≈ 9.","Учитывай активность, короля и конкретную тактику."],"question":"Всегда ли ладья лучше слона и двух пешек?","options":["Всегда","Не всегда: позиция и активность имеют значение","Ладья всегда хуже"],"answer":1,"explanation":"Материальная шкала — ориентир. Конкретная позиция может сильно менять реальную ценность фигур."},
    {"id":"conversion-trade","section":"Реализация преимущества","title":"Когда выгодно менять фигуры","level":"700–1200","summary":"При материальном перевесе размены фигур часто уменьшают контригру соперника.","steps":["Сначала проверь безопасность короля.","Рассмотри размен ферзей.","Меняй активные фигуры соперника.","Не разменивай автоматически все пешки."],"question":"Ты выигрываешь фигуру. Что обычно полезно?","options":["Сохранить максимум атакующих фигур соперника","Упростить позицию выгодными разменами","Отдать ферзя"],"answer":1,"explanation":"Чем меньше активных фигур у соперника, тем меньше его тактических шансов."},
    {"id":"conversion-counterplay","section":"Реализация преимущества","title":"Уменьшай контригру","level":"800–1300","summary":"Победа часто состоит не в новой атаке, а в лишении соперника шансов.","steps":["Найди самую активную фигуру соперника.","Предложи выгодный размен.","Закрой опасные линии.","Не создавай ненужных слабостей."],"question":"Что опаснее при большом материальном перевесе?","options":["Спокойное упрощение","Ненужная авантюрная атака","Размен ферзей"],"answer":1,"explanation":"Когда ты уже выигрываешь, риск часто работает только на соперника."},
    {"id":"position-worst","section":"Позиционная игра","title":"Улучши худшую фигуру","level":"800–1400","summary":"Если тактики нет, найди свою наименее активную фигуру и улучшай её.","steps":["Оцени активность каждой фигуры.","Найди фигуру без полезных полей.","Найди маршрут к лучшему полю.","Проверь, не создаёт ли ход тактических проблем."],"question":"Что делать, если нет шахов, взятий и угроз?","options":["Случайно двигать пешку","Улучшить худшую фигуру","Сразу жертвовать фигуру"],"answer":1,"explanation":"Это простой и надёжный способ находить позиционные планы."},
    {"id":"position-open-file","section":"Позиционная игра","title":"Открытая линия для ладьи","level":"800–1400","summary":"Ладьи становятся сильнее на линиях без своих пешек.","steps":["Найди открытую или полуоткрытую линию.","Поставь туда ладью.","При возможности удвой ладьи.","Ищи проникновение на 7-ю/2-ю горизонталь."],"question":"Где ладья обычно активнее?","options":["За заблокированными своими пешками","На открытой линии","В углу без задач"],"answer":1,"explanation":"Открытая линия даёт ладье дальнобойность и возможность проникновения."},
    {"id":"position-outpost","section":"Позиционная игра","title":"Форпост","level":"900–1500","summary":"Сильное поле для фигуры, особенно коня, которое трудно атаковать пешкой.","steps":["Найди слабое поле в лагере соперника.","Проверь, могут ли пешки соперника выгнать фигуру.","Поддержи фигуру своей пешкой."],"question":"Какая фигура особенно любит форпост?","options":["Конь","Король в дебюте","Пешка на первой горизонтали"],"answer":0,"explanation":"Конь на устойчивом центральном поле может контролировать много важных клеток."},
    {"id":"pawn-isolated","section":"Пешки","title":"Изолированная пешка","level":"900–1500","summary":"У неё нет соседних пешек, поэтому её труднее защищать пешками.","steps":["Определи изолированную пешку.","Оцени её динамические плюсы — пространство и линии.","В эндшпиле учитывай её долгосрочную слабость."],"question":"Главный минус изолированной пешки?","options":["Её нельзя защитить соседней пешкой","Она всегда превращается в ферзя","Она даёт шах"],"answer":0,"explanation":"Защищать её приходится фигурами, что может связывать силы."},
    {"id":"pawn-passed","section":"Пешки","title":"Проходная пешка","level":"700–1300","summary":"Пешка, которой не мешают пешки соперника на своей и соседних вертикалях.","steps":["Создай проходную.","Продвигай её с поддержкой фигур.","Связывай фигуры соперника необходимостью её блокировать."],"question":"Почему проходная сильна?","options":["Она угрожает превращением","Она не может двигаться","Она всегда защищена ферзём"],"answer":0,"explanation":"Соперник вынужден тратить ресурсы на остановку превращения."},
    {"id":"endgame-king","section":"Эндшпиль","title":"Активный король","level":"600–1200","summary":"В эндшпиле король становится активной боевой фигурой.","steps":["После размена ферзей оцени безопасность входа короля.","Веди короля к центру.","Атакуй слабые пешки."],"question":"Где обычно полезен король в эндшпиле?","options":["В центре","Всегда в углу","За пределами доски"],"answer":0,"explanation":"Без угроз раннего мата король может активно поддерживать пешки и атаковать слабости."},
    {"id":"endgame-square","section":"Эндшпиль","title":"Правило квадрата","level":"500–1000","summary":"Быстрый способ понять, догонит ли король проходную пешку.","steps":["Построй мысленный квадрат от пешки до поля превращения.","Если король входит в квадрат своим ходом — обычно догоняет.","Учитывай очередь хода."],"question":"Для чего нужно правило квадрата?","options":["Понять, догонит ли король пешку","Выбрать дебют","Посчитать ценность ферзя"],"answer":0,"explanation":"Оно позволяет оценить гонку пешки и короля без расчёта каждого хода."},
    {"id":"endgame-opposition","section":"Эндшпиль","title":"Оппозиция королей","level":"700–1200","summary":"Ключевой приём пешечных окончаний.","steps":["Поставь короля напротив короля соперника через одно поле.","Заставь соперника уступить важное поле.","Используй очередь хода для проникновения."],"question":"Зачем нужна оппозиция?","options":["Чтобы выиграть ключевые поля королём","Чтобы дать мат ферзём","Чтобы сделать рокировку"],"answer":0,"explanation":"Оппозиция часто решает, сможет ли король проникнуть к пешке или полю превращения."},
    {"id":"defense-trade","section":"Защита","title":"Размени атакующую фигуру","level":"700–1300","summary":"Иногда лучший способ защиты — убрать главного участника атаки.","steps":["Найди наиболее опасную атакующую фигуру.","Проверь возможность её размена.","Сравни, что остаётся после размена."],"question":"Что часто помогает против атаки на короля?","options":["Размен ключевой атакующей фигуры","Открыть ещё линии к своему королю","Отдать все пешки"],"answer":0,"explanation":"Без ключевой фигуры координация атаки часто исчезает."},
    {"id":"defense-return","section":"Защита","title":"Когда вернуть материал","level":"900–1500","summary":"Иногда лучше отдать часть перевеса, чтобы полностью погасить атаку.","steps":["Оцени реальность угрозы матом.","Найди материал, который можно вернуть с темпом.","Стремись перейти в безопасную позицию с оставшимся перевесом."],"question":"Можно ли добровольно вернуть пешку или качество при защите?","options":["Никогда","Да, если это снимает опасную атаку и сохраняет преимущество","Только на первом ходу"],"answer":1,"explanation":"Материальный перевес бесполезен, если король получает мат."},
]
